`timescale 1ns / 1ps
`default_nettype none

// Synthesis tops for E3a/E3b out-of-context synthesis (fpga/kv260/tcl/run_e3_synth.tcl).
// model_paths.vh (generated by scripts/sim/run_e3.py into build/e3) gives the $readmemh files of the
// frozen E2 reference model (subject 1, P2 test day 3, seed 0) and the DSP coefficients.

`include "model_paths.vh"

// ---------------- DSP alone ----------------
module emg_dsp_top (
    input  wire clk, input wire rst,
    input  wire [3:0] cfg_sec_en, input wire cfg_clear,
    input  wire coef_we, input wire [7:0] coef_addr, input wire [17:0] coef_wdata,
    input  wire s_tvalid, output wire s_tready, input wire [127:0] s_tdata, input wire [79:0] s_tuser, input wire s_tlast,
    output wire m_tvalid, input wire m_tready, output wire [127:0] m_tdata, output wire [79:0] m_tuser, output wire m_tlast,
    output wire [31:0] stat_frames_in, output wire [31:0] stat_frames_out, output wire [31:0] stat_out_sat,
    output wire [31:0] stat_int_sat, output wire [31:0] stat_resets, output wire stat_ovf_sticky, output wire busy
);
    emg_dsp #(.N_CH(4), .N_SEC(4), .COEF_FILE(`DSP_COEF_FILE)) u_dsp (
        .clk(clk), .rst(rst), .cfg_sec_en(cfg_sec_en), .cfg_clear(cfg_clear),
        .coef_we(coef_we), .coef_addr(coef_addr), .coef_wdata(coef_wdata),
        .s_tvalid(s_tvalid), .s_tready(s_tready), .s_tdata(s_tdata), .s_tuser(s_tuser), .s_tlast(s_tlast),
        .m_tvalid(m_tvalid), .m_tready(m_tready), .m_tdata(m_tdata), .m_tuser(m_tuser), .m_tlast(m_tlast),
        .stat_frames_in(stat_frames_in), .stat_frames_out(stat_frames_out), .stat_out_sat(stat_out_sat),
        .stat_int_sat(stat_int_sat), .stat_resets(stat_resets), .stat_ovf_sticky(stat_ovf_sticky), .busy(busy));
endmodule

// ---------------- CNN alone ----------------
module emg_cnn_top (
    input  wire clk, input wire rst,
    input  wire s_tvalid, output wire s_tready, input wire [127:0] s_tdata, input wire [79:0] s_tuser, input wire s_tlast,
    output wire res_valid, input wire res_ready, output wire [191:0] res_scores, output wire [3:0] res_argmax,
    output wire [31:0] res_end, output wire [31:0] res_seq, output wire [31:0] res_ts, output wire [7:0] res_seg,
    output wire [31:0] res_count,
    output wire dbg_valid, output wire [2:0] dbg_layer, output wire [5:0] dbg_ch, output wire [23:0] dbg_step,
    output wire [7:0] dbg_seg, output wire [31:0] dbg_acc, output wire [7:0] dbg_act,
    input  wire wr_en, input wire [3:0] wr_mem, input wire [12:0] wr_addr, input wire [31:0] wr_data,
    output wire [31:0] stat_frames, output wire [31:0] stat_results, output wire [31:0] stat_resets,
    output wire [31:0] stat_not_post_dsp, output wire [31:0] stat_sat1, output wire [31:0] stat_sat2,
    output wire [31:0] stat_sat3, output wire busy
);
    emg_cnn #(.SETTLE(0),
        .W1_FILE(`W1_FILE), .B1_FILE(`B1_FILE), .M1_FILE(`M1_FILE), .SH1_FILE(`SH1_FILE),
        .W2_FILE(`W2_FILE), .B2_FILE(`B2_FILE), .M2_FILE(`M2_FILE), .SH2_FILE(`SH2_FILE),
        .W3_FILE(`W3_FILE), .B3_FILE(`B3_FILE), .M3_FILE(`M3_FILE), .SH3_FILE(`SH3_FILE),
        .FCW_FILE(`FCW_FILE), .FCB_FILE(`FCB_FILE)) u_cnn (
        .clk(clk), .rst(rst),
        .s_tvalid(s_tvalid), .s_tready(s_tready), .s_tdata(s_tdata), .s_tuser(s_tuser), .s_tlast(s_tlast),
        .res_valid(res_valid), .res_ready(res_ready), .res_scores(res_scores), .res_argmax(res_argmax),
        .res_end(res_end), .res_seq(res_seq), .res_ts(res_ts), .res_seg(res_seg), .res_count(res_count),
        .dbg_valid(dbg_valid), .dbg_layer(dbg_layer), .dbg_ch(dbg_ch), .dbg_step(dbg_step), .dbg_seg(dbg_seg),
        .dbg_acc(dbg_acc), .dbg_act(dbg_act),
        .wr_en(wr_en), .wr_mem(wr_mem), .wr_addr(wr_addr), .wr_data(wr_data),
        .stat_frames(stat_frames), .stat_results(stat_results), .stat_resets(stat_resets),
        .stat_not_post_dsp(stat_not_post_dsp), .stat_sat1(stat_sat1), .stat_sat2(stat_sat2), .stat_sat3(stat_sat3),
        .busy(busy));
endmodule

// ---------------- DSP -> CNN over ESI (debug port and weight-write port not brought out) ----------------
module emg_e3_top (
    input  wire clk, input wire rst,
    input  wire [3:0] cfg_sec_en,
    input  wire s_tvalid, output wire s_tready, input wire [127:0] s_tdata, input wire [79:0] s_tuser, input wire s_tlast,
    output wire res_valid, input wire res_ready, output wire [191:0] res_scores, output wire [3:0] res_argmax,
    output wire [31:0] res_end, output wire [31:0] res_seq, output wire [31:0] res_ts, output wire [31:0] res_count,
    output wire [31:0] dsp_out_sat, output wire [31:0] dsp_int_sat, output wire dsp_ovf, output wire [31:0] cnn_frames,
    output wire busy
);
    wire         c_tvalid, c_tready, c_tlast;
    wire [127:0] c_tdata;
    wire [79:0]  c_tuser;
    wire [31:0]  d_in, d_out, d_res;
    wire         d_busy, c_busy;
    emg_dsp #(.N_CH(4), .N_SEC(4), .COEF_FILE(`DSP_COEF_FILE)) u_dsp (
        .clk(clk), .rst(rst), .cfg_sec_en(cfg_sec_en), .cfg_clear(1'b0),
        .coef_we(1'b0), .coef_addr(8'd0), .coef_wdata(18'd0),
        .s_tvalid(s_tvalid), .s_tready(s_tready), .s_tdata(s_tdata), .s_tuser(s_tuser), .s_tlast(s_tlast),
        .m_tvalid(c_tvalid), .m_tready(c_tready), .m_tdata(c_tdata), .m_tuser(c_tuser), .m_tlast(c_tlast),
        .stat_frames_in(d_in), .stat_frames_out(d_out), .stat_out_sat(dsp_out_sat), .stat_int_sat(dsp_int_sat),
        .stat_resets(d_res), .stat_ovf_sticky(dsp_ovf), .busy(d_busy));
    emg_cnn #(.SETTLE(0),
        .W1_FILE(`W1_FILE), .B1_FILE(`B1_FILE), .M1_FILE(`M1_FILE), .SH1_FILE(`SH1_FILE),
        .W2_FILE(`W2_FILE), .B2_FILE(`B2_FILE), .M2_FILE(`M2_FILE), .SH2_FILE(`SH2_FILE),
        .W3_FILE(`W3_FILE), .B3_FILE(`B3_FILE), .M3_FILE(`M3_FILE), .SH3_FILE(`SH3_FILE),
        .FCW_FILE(`FCW_FILE), .FCB_FILE(`FCB_FILE)) u_cnn (
        .clk(clk), .rst(rst),
        .s_tvalid(c_tvalid), .s_tready(c_tready), .s_tdata(c_tdata), .s_tuser(c_tuser), .s_tlast(c_tlast),
        .res_valid(res_valid), .res_ready(res_ready), .res_scores(res_scores), .res_argmax(res_argmax),
        .res_end(res_end), .res_seq(res_seq), .res_ts(res_ts), .res_seg(), .res_count(res_count),
        .dbg_valid(), .dbg_layer(), .dbg_ch(), .dbg_step(), .dbg_seg(), .dbg_acc(), .dbg_act(),
        .wr_en(1'b0), .wr_mem(4'd0), .wr_addr(13'd0), .wr_data(32'd0),
        .stat_frames(cnn_frames), .stat_results(), .stat_resets(), .stat_not_post_dsp(), .stat_sat1(),
        .stat_sat2(), .stat_sat3(), .busy(c_busy));
    assign busy = d_busy | c_busy;
endmodule

`default_nettype wire
